<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Animated Solar System</title>
<style>
  body{margin:0;background:#000;}
  canvas{display:block;}
</style>
</head>
<body>
<canvas id="canvas"></canvas>
<script>
const canvas = document.getElementById('canvas');
const ctx = canvas.getContext('2d');
let width, height, centerX, centerY;

// Resize canvas to fill the window
function resize() {
  width = canvas.width = window.innerWidth;
  height = canvas.height = window.innerHeight;
  centerX = width / 2;
  centerY = height / 2;
}
window.addEventListener('resize', resize);
resize();

// Create a simple starfield
const stars = [];
const starCount = 200;
for (let i = 0; i < starCount; i++) {
  stars.push({
    x: Math.random() * width,
    y: Math.random() * height,
    radius: Math.random() * 1.5 + 0.5,
    alpha: Math.random() * 0.5 + 0.5
  });
}

// Planet definitions
const planets = [
  { name: 'Mercury',  color: '#a0a0a0', radius: 2,   distance: 80,  speed: 4.8 },
  { name: 'Venus',    color: '#f5a623', radius: 3,   distance: 110,  speed: 3.5 },
  { name: 'Earth',    color: '#2c7ae5', radius: 3.5, distance: 140,  speed: 3.0 },
  { name: 'Mars',     color: '#e74c3c', radius: 3,   distance: 170,  speed: 2.7 },
  { name: 'Jupiter',  color: '#d35400', radius: 9,   distance: 220,  speed: 1.6 },
  { name: 'Saturn',   color: '#f1c40f', radius: 8.5, distance: 260,  speed: 1.4 },
  { name: 'Uranus',   color: '#27ae60', radius: 7,   distance: 300,  speed: 1.1 },
  { name: 'Neptune',  color: '#3498db', radius: 7,   distance: 340,  speed: 0.9 }
];

// Each planet will track its current angle
planets.forEach(p => p.angle = Math.random() * Math.PI * 2);

// Animation loop
let lastTime = performance.now();
function animate(now) {
  const dt = (now - lastTime) / 1000; // seconds
  lastTime = now;

  ctx.clearRect(0, 0, width, height);

  // Draw starfield
  stars.forEach(star => {
    ctx.save();
    ctx.fillStyle = `rgba(255,255,255,${star.alpha})`;
    ctx.beginPath();
    ctx.arc(star.x, star.y, star.radius, 0, Math.PI*2);
    ctx.fill();
    ctx.restore();
  });

  // Draw Sun
  ctx.save();
  ctx.fillStyle = '#ffd700';
  ctx.beginPath();
  ctx.arc(centerX, centerY, 20, 0, Math.PI*2);
  ctx.fill();
  ctx.restore();

  // Draw planets
  planets.forEach(p => {
    p.angle += p.speed * dt;
    const x = centerX + Math.cos(p.angle) * p.distance;
    const y = centerY + Math.sin(p.angle) * p.distance;

    // Planet body
    ctx.save();
    ctx.fillStyle = p.color;
    ctx.beginPath();
    ctx.arc(x, y, p.radius, 0, Math.PI*2);
    ctx.fill();
    ctx.restore();

    // Label
    ctx.save();
    ctx.font = '12px Arial';
    ctx.fillStyle = '#fff';
    ctx.fillText(p.name, x + p.radius + 2, y + p.radius + 2);
    ctx.restore();
  });

  requestAnimationFrame(animate);
}
requestAnimationFrame(animate);
</script>
</body>
</html>
```

The script renders a starfield, draws the Sun at the center, and animates eight planets orbiting at different speeds, each labeled, using requestAnimationFrame on a full‑screen canvas.
